<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><section class="sd-dashboard-card"><div class="sd-card-heading"><h2><?php esc_html_e( 'Suggested people', 'social-discovery' ); ?></h2><a href="<?php echo esc_url( sd_home_url( 'discover' ) ); ?>"><?php esc_html_e( 'Discover', 'social-discovery' ); ?></a></div><?php if ( function_exists( 'sd_core_recommend_members' ) ) : $members = sd_core_recommend_members( get_current_user_id(), 4 ); if ( ! empty( $members ) ) : ?><ul class="sd-dashboard-list"><?php foreach ( $members as $member ) : ?><li><a href="<?php echo esc_url( sd_get_member_url( $member->ID ) ); ?>"><img src="<?php echo esc_url( sd_avatar( $member->ID, 40 ) ); ?>" alt=""><strong><?php echo esc_html( sd_user_name( $member->ID ) ); ?></strong></a></li><?php endforeach; ?></ul><?php else : ?><p class="sd-muted"><?php esc_html_e( 'Recommendations will appear when public interests are available.', 'social-discovery' ); ?></p><?php endif; else : ?><p class="sd-muted"><?php esc_html_e( 'People discovery is available when Social Discovery Core is active.', 'social-discovery' ); ?></p><?php endif; ?></section>
